-- 0109_chain_library_complete_fields.sql
-- Adds doc fields that had no DB column and backfills all 88 chains from
-- OGz 2.0 ChainLibrary v2 Complete.docx: video_motion_prompt (i2v animation instruction),
-- saudi_adaptation, intent[], frequency. Also backfills requires_ref_img and the 5 video
-- negative prompts where the doc provides them. Idempotent: ADD COLUMN IF NOT EXISTS + keyed UPDATEs.

ALTER TABLE chains ADD COLUMN IF NOT EXISTS video_motion_prompt TEXT;
ALTER TABLE chains ADD COLUMN IF NOT EXISTS saudi_adaptation     TEXT;
ALTER TABLE chains ADD COLUMN IF NOT EXISTS intent               TEXT[];
ALTER TABLE chains ADD COLUMN IF NOT EXISTS frequency            TEXT;

